/** Pure month figures for the dashboard KPI cards. Amounts in cents. */

type Entry = { type: string; amountCents: number; status?: string; recurringId: string | null };

export type ExpenseSplit = {
  fixedCents: number;
  fixedCount: number;
  fixedPaidCount: number;
  variableCents: number;
  variableCount: number;
};

/**
 * Splits a month's expenses into fixed (generated by a recurring template) and variable.
 * `projected` are future recurring occurrences that are not stored yet; they count as fixed, unpaid.
 */
export function splitExpenses(entries: Entry[], projected: Omit<Entry, "status">[] = []): ExpenseSplit {
  const split: ExpenseSplit = { fixedCents: 0, fixedCount: 0, fixedPaidCount: 0, variableCents: 0, variableCount: 0 };
  for (const e of entries) {
    if (e.type !== "EXPENSE" || e.status === "SKIPPED") continue;
    if (e.recurringId) {
      split.fixedCents += e.amountCents;
      split.fixedCount += 1;
      if (e.status === "PAID") split.fixedPaidCount += 1;
    } else {
      split.variableCents += e.amountCents;
      split.variableCount += 1;
    }
  }
  for (const p of projected) {
    if (p.type !== "EXPENSE") continue;
    split.fixedCents += p.amountCents;
    split.fixedCount += 1;
  }
  return split;
}

/** part / whole as a 0..1 ratio, 0 when whole is not positive. */
export function ratio(part: number, whole: number): number {
  return whole > 0 ? part / whole : 0;
}

/** Relative change from `previous` to `current`, or null when there is no base to compare. */
export function percentChange(current: number, previous: number): number | null {
  if (previous <= 0) return null;
  return (current - previous) / previous;
}
